PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, title TEXT NOT NULL, owner_hash TEXT NOT NULL, phase TEXT NOT NULL DEFAULT 'upload', created INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS participants (id TEXT PRIMARY KEY, room TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS videos (id TEXT PRIMARY KEY, room TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, participant TEXT NOT NULL REFERENCES participants(id) ON DELETE CASCADE, title TEXT NOT NULL, stance TEXT NOT NULL, law TEXT NOT NULL, context TEXT NOT NULL, counter TEXT NOT NULL, duration REAL NOT NULL, bytes INTEGER NOT NULL, mime TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'uploading', created INTEGER NOT NULL, UNIQUE(room,participant));
CREATE TABLE IF NOT EXISTS watched (participant TEXT NOT NULL REFERENCES participants(id) ON DELETE CASCADE, video TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE, seconds REAL NOT NULL DEFAULT 0, last_seen INTEGER NOT NULL, PRIMARY KEY(participant,video));
CREATE TABLE IF NOT EXISTS votes (participant TEXT PRIMARY KEY REFERENCES participants(id) ON DELETE CASCADE, room TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, choice TEXT NOT NULL CHECK(choice IN ('Gefängnis','Psychiatrie')), reason TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS videos_room ON videos(room);
CREATE INDEX IF NOT EXISTS participants_room ON participants(room);
CREATE INDEX IF NOT EXISTS votes_room ON votes(room);

CREATE TABLE IF NOT EXISTS confirmations (id TEXT PRIMARY KEY, note TEXT NOT NULL, created INTEGER NOT NULL);
